fn sum_upto(n: Int) -> Int {
    var total = 0;
    var i = 1;
    while i <= n {
        total = total + i;
        i = i + 1;
    }
    total
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let n1 = 12;
    let s1 = sum_upto(n: n1);
    io.write(text: n1.to_text().concat(other: ": ").concat(other: s1.to_text()).concat(other: "\n"))?;

    let n2 = 30;
    let s2 = sum_upto(n: n2);
    io.write(text: n2.to_text().concat(other: ": ").concat(other: s2.to_text()).concat(other: "\n"))?;

    let n3 = 7;
